import { Playfair_Display, Roboto } from "next/font/google";

const headingFont = Playfair_Display({
  subsets: ["latin"],
  weight: ["600", "700"],
});

const subtitleFont = Roboto({
  subsets: ["latin"],
  weight: ["400"],
});

export default function BlogHeader() {
  return (
    <header>
      <h1 className={headingFont.className}>My Personal Blog</h1>
      <p className={subtitleFont.className}>Thoughts, ideas, and musings</p>
    </header>
  );
}
